// Per-version ABI tables.
//
// Each sub-module is generated by `gen/nvabi_gen.py` from gVisor's nvproxy and
// describes the frontend ioctls of one NVIDIA driver version. The backend
// selects a table at runtime once `NV_ESC_CHECK_VERSION_STR` has told it which
// driver the host is running.

pub mod v535_129_03;
pub mod v565_57_01;
pub mod v580_178_04;
pub mod v595_71_05;
pub mod v610_57_04;
pub mod v620_30_00;
pub mod v620_32_00;
pub mod v620_47_00;
pub mod v620_51_00;

use crate::version::DriverVersion;

/// How the device must handle one escape.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum IoctlKind {
    /// Copy params in, call the host ioctl, copy params out. No handles, no
    /// mappings, no embedded pointers.
    Simple,
    /// Carries an embedded file descriptor that must be translated from a guest
    /// handle to a host fd before the host ioctl is issued.
    FdCarrying,
    /// Establishes a host mapping. The device allocates SHM and returns an
    /// offset; see `device/src/mmap.rs`.
    Mapping,
    /// `NV_ESC_RM_CONTROL`: nested dispatch on the embedded control command.
    RmControl,
    /// `NV_ESC_RM_ALLOC`: nested dispatch on the embedded allocation class.
    RmAlloc,
    /// `NV_ESC_RM_VID_HEAP_CONTROL`: a union whose active arm depends on the
    /// requested function.
    VidHeapControl,
    /// `NV_ESC_RM_IDLE_CHANNELS`: carries three guest pointer arrays.
    IdleChannels,
    /// A variable-length byte array with no fixed parameter struct, sized by
    /// the ioctl number at call time.
    Bytes,
    /// `NV_ESC_RM_GET_EVENT_DATA`: carries a pointer to the one fixed-size
    /// `NvUnixEvent` RM writes; the device supplies that buffer. Not in
    /// nvproxy -- added by `nvabi_gen.py`'s `CONDUIT_EXTRA`.
    EventData,
}

/// One entry in a per-version ioctl table.
pub struct IoctlEntry {
    /// The `NV_ESC_*` escape, i.e. bits 7:0 of the Linux ioctl number.
    pub escape: u32,
    /// `sizeof` the parameter struct for this driver version, or `None` when
    /// the ioctl is variable length.
    pub param_size: Option<u32>,
    /// Further sizes this release's kernel module takes for the same escape.
    /// Only `NV_ESC_RM_ALLOC` has one (NVOS21, 32 bytes, beside NVOS64's 48);
    /// see `ALSO_ACCEPTS` in `nvabi_gen.py`.
    pub also: &'static [u32],
    pub kind: IoctlKind,
}

impl IoctlEntry {
    /// Whether the kernel module of this release takes `size` bytes here.
    /// A variable-length escape takes any.
    pub fn accepts(&self, size: u32) -> bool {
        match self.param_size {
            None => true,
            Some(own) => own == size || self.also.contains(&size),
        }
    }
}

/// A supported driver version and the table it selects.
struct Profile {
    version: DriverVersion,
    table: fn() -> &'static [IoctlEntry],
}

/// Profiles in ascending version order.
static PROFILES: &[Profile] = &[
    Profile {
        version: DriverVersion::new(535, 129, 3),
        table: v535_129_03::table,
    },
    Profile {
        version: DriverVersion::new(565, 57, 1),
        table: v565_57_01::table,
    },
    Profile {
        version: DriverVersion::new(580, 178, 4),
        table: v580_178_04::table,
    },
    Profile {
        version: DriverVersion::new(595, 71, 5),
        table: v595_71_05::table,
    },
    Profile {
        version: DriverVersion::new(610, 57, 4),
        table: v610_57_04::table,
    },
];

/// Select the profile for `v`.
///
/// Profiles key off **ranges, not points**: a release between two known
/// versions selects the lower profile, which is what keeps the per-release cost
/// small. A version older than every profile has no table and returns `None` --
/// guessing downwards would mean forwarding ioctls whose layout we have never
/// seen.
pub fn table_for(v: DriverVersion) -> Option<&'static [IoctlEntry]> {
    PROFILES
        .iter()
        .rev()
        .find(|p| p.version <= v)
        .map(|p| (p.table)())
}

/// Whether a driver version resolves to a table at all.
pub fn is_supported(v: DriverVersion) -> bool {
    table_for(v).is_some()
}

/// Look up one escape in a table.
pub fn lookup(table: &'static [IoctlEntry], escape: u32) -> Option<&'static IoctlEntry> {
    table.iter().find(|e| e.escape == escape)
}

/// The versions with a profile of their own, ascending.
pub fn supported_versions() -> impl Iterator<Item = DriverVersion> {
    PROFILES.iter().map(|p| p.version)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn exact_version_selects_its_own_profile() {
        let t = table_for(DriverVersion::new(580, 178, 4)).expect("580.178.04 has a profile");
        assert!(std::ptr::eq(t, v580_178_04::table()));
    }

    #[test]
    fn version_between_profiles_selects_the_lower_one() {
        // 570.x sits between the 565.57.01 and 580 profiles.
        let t = table_for(DriverVersion::new(570, 86, 15)).expect("falls back to 565.57.01");
        assert!(std::ptr::eq(t, v565_57_01::table()));
    }

    #[test]
    fn version_above_every_profile_selects_the_highest() {
        let t = table_for(DriverVersion::new(610, 43, 2)).expect("falls back to 595");
        assert!(std::ptr::eq(t, v595_71_05::table()));
    }

    #[test]
    fn the_565_77_release_uses_the_565_57_01_profile() {
        // gVisor's nvproxy has 565.57.01 and no 565.77; open-gpu-kernel-modules
        // differs between the two in no escape struct or ioctl number, so
        // 565.77 selects 565.57.01 by range. The 535 profile it would otherwise
        // get has a 40-byte UNMAP_MEMORY_DMA and no WAIT_OPEN_COMPLETE.
        let t = table_for(DriverVersion::new(565, 77, 0)).expect("565.77 has a profile");
        assert!(std::ptr::eq(t, v565_57_01::table()));
    }

    #[test]
    fn version_below_every_profile_is_unsupported() {
        assert!(table_for(DriverVersion::new(470, 0, 0)).is_none());
        assert!(!is_supported(DriverVersion::new(470, 0, 0)));
    }

    #[test]
    fn profiles_are_sorted_ascending() {
        let vs: Vec<_> = supported_versions().collect();
        let mut sorted = vs.clone();
        sorted.sort();
        assert_eq!(vs, sorted, "PROFILES must stay in ascending order");
    }

    /// Escape x release -> accepted sizes, one row each, as the table says.
    fn sizes_tsv() -> String {
        let mut out = String::from("release\tescape\tname\tsizes\n");
        for p in PROFILES {
            for e in (p.table)() {
                let sizes = match e.param_size {
                    None => "any".to_string(),
                    Some(own) => std::iter::once(own)
                        .chain(e.also.iter().copied())
                        .map(|s| s.to_string())
                        .collect::<Vec<_>>()
                        .join(","),
                };
                let name = crate::names::escape(e.escape).unwrap_or("?");
                out += &format!("{}\t{:#04x}\t{name}\t{sizes}\n", p.version, e.escape);
            }
        }
        out
    }

    /// The fixture the guest's C test (`guest/linux/test/escape_test.c`) reads:
    /// the same table the backend checks calls against and sends the guest.
    /// Regenerate with `UPDATE_FIXTURES=1 cargo test -p abi escape_size`.
    #[test]
    fn the_escape_size_fixture_is_the_tables() {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/escape_sizes.tsv");
        let now = sizes_tsv();
        if std::env::var_os("UPDATE_FIXTURES").is_some() {
            std::fs::write(path, &now).unwrap();
        }
        assert_eq!(
            std::fs::read_to_string(path).expect("fixtures/escape_sizes.tsv"),
            now,
            "stale: run UPDATE_FIXTURES=1 cargo test -p abi escape_size"
        );
    }

    /// RM_ALLOC takes NVOS21 (32) and NVOS64 (48) in every release.
    #[test]
    fn rm_alloc_takes_both_its_sizes_in_every_release() {
        for p in PROFILES {
            let e = lookup((p.table)(), crate::ioctl::NV_ESC_RM_ALLOC).unwrap();
            assert!(e.accepts(32) && e.accepts(48), "{}", p.version);
            assert!(!e.accepts(40) && !e.accepts(0), "{}", p.version);
        }
    }
}
